export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4;
  const g = inputs.gravity ?? 9.8;

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);

  const tToss = Math.min(time, 2 * apexTime);
  const tossedVelocity = u - g * tToss;
  const tossedAcceleration = -g;
  const tossedHeight = Math.max(0, u * tToss - 0.5 * g * tToss * tToss);

  const isHeld = time < apexTime;
  const dropVelocity = isHeld ? 0 : -g * (time - apexTime);
  const dropAcceleration = isHeld ? 0 : -g;
  const dropHeight = isHeld ? apexHeight : Math.max(0, apexHeight - 0.5 * g * (time - apexTime) * (time - apexTime));

  const y0 = 360;
  const scale = 110;
  const hToY = (h) => y0 - h * scale;

  const xToss = 160;
  const xDrop = 480;

  const tossY = hToY(tossedHeight);
  const dropY = hToY(dropHeight);
  const apexY = hToY(apexHeight);

  const objects = [];

  objects.push(...sdk.panel({ id: "lane.toss", x: 20, y: 30, w: 280, h: 360, title: "Toss Lane", state: time < apexTime - 0.001 ? "Rising" : Math.abs(time - apexTime) <= 0.001 ? "At the top" : time > 2 * apexTime ? "At launch height" : "Falling" }));
  objects.push(...sdk.panel({ id: "lane.drop", x: 340, y: 30, w: 280, h: 360, title: "Drop Lane", state: isHeld ? "Held in place" : Math.abs(time - apexTime) <= 0.001 ? "Just released" : dropHeight <= 0.001 ? "At launch height" : "Falling together" }));

  objects.push(sdk.axis("axis.toss", { x: 50, y: y0, length: 300, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: 370, y: y0, length: 300, orientation: "y", min: 0, max: 2.2, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  objects.push(...sdk.gate("gate", xDrop, apexY, { open: !isHeld, w: 40, label: "Release Gate" }));

  if (!isHeld) {
    objects.push(sdk.circle("apex.ghost.toss", xToss, apexY, 26, { role: "neutral", opacity: 0.3 }));
    objects.push(sdk.circle("apex.ghost.drop", xDrop, apexY, 26, { role: "neutral", opacity: 0.3 }));
  }

  objects.push(sdk.circle("ball.toss", xToss, tossY, 26, { role: "learner" }));
  objects.push(sdk.circle("ball.drop", xDrop, dropY, 26, { role: "tutor" }));

  const vScale = 15;
  const aScale = 12;

  objects.push(...sdk.vector("vec.v.toss", { x: xToss - 18, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: vScale, label: "v", role: "learner" }));
  objects.push(...sdk.vector("vec.a.toss", { x: xToss + 18, y: tossY }, { value: tossedAcceleration, direction: "up" }, { scale: aScale, label: "a", role: "warning" }));

  objects.push(...sdk.vector("vec.v.drop", { x: xDrop - 18, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: vScale, label: "v", role: "tutor" }));
  objects.push(...sdk.vector("vec.a.drop", { x: xDrop + 18, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: aScale, label: "a", role: "warning" }));

  objects.push(...sdk.callout(xToss + 35, tossY - 20, [`v: ${sdk.format(tossedVelocity, 2)} m/s`, `a: ${sdk.format(tossedAcceleration, 2)} m/s²`], { id: "callout.toss", role: "learner" }));
  objects.push(...sdk.callout(xDrop + 35, dropY - 20, [`v: ${sdk.format(dropVelocity, 2)} m/s`, `a: ${sdk.format(dropAcceleration, 2)} m/s²`], { id: "callout.drop", role: "tutor" }));

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime,
    apexHeight,
    tossedVelocity,
    tossedAcceleration,
    tossedHeight,
    dropVelocity,
    dropAcceleration,
    dropHeight
  };

  const readouts = [
    { id: "tossedVelocity", value: tossedVelocity },
    { id: "tossedAcceleration", value: tossedAcceleration },
    { id: "dropVelocity", value: dropVelocity },
    { id: "dropAcceleration", value: dropAcceleration }
  ];

  return {
    frame: sdk.frame(objects, { width: 640, height: 420, readouts }),
    quantities
  };
}
